SELECT (CASE WHEN (trainsuk1_2.timetable = 'D13') THEN 'Dec 13 TT (weekdays)' WHEN (trainsuk1_2.timetable = 'M14') THEN 'May 14 TT (weekdays)' WHEN (trainsuk1_2.timetable = 'D14') THEN 'Dec 14 TT (weekdays)' WHEN (trainsuk1_2.timetable = 'M15') THEN 'May 15 TT (weekdays)' WHEN (trainsuk1_2.timetable = 'D15') THEN 'Dec 15 TT (weekdays)' WHEN (trainsuk1_2.timetable = 'M16') THEN 'May 16 TT (weekdays)' WHEN (trainsuk1_2.timetable = 'D16') THEN 'Dec 16 TT (weekdays)' WHEN (trainsuk1_2.timetable = 'M17') THEN 'May 17 TT (weekdays)' WHEN (trainsuk1_2.timetable = 'D17') THEN ((((('Dec 17 TT (weekdays) to ' || CAST(3 AS TEXT)) || '/') || CAST(2 AS TEXT)) || '/') || CAST(2018 AS TEXT)) ELSE trainsuk1_2.timetable END) AS c_timetable_for_title__copy_ FROM trainsuk1_2 WHERE ((trainsuk1_2.timetable = 'M18') AND (trainsuk1_2.v_headcode_description = '1A04London Liverpool Street to Harwich Town at 06:38')) GROUP BY c_timetable_for_title__copy_;
